/* Preview-mode data wrapper — used ONLY when /?preview=1 is in the URL.
 *
 * Production frontend continues to read the bundled /assets/data/*.json
 * files (regenerated by studio/migrate/pull-data.ts on each build). This
 * file is the alternative path: it goes directly to Sanity so editors can
 * see in-progress changes in the Sanity Presentation iframe.
 *
 * Loaded via <script src="/assets/js/roofy-data.js"></script> in every
 * HTML head — but only activates if window.location.search includes preview=1.
 *
 * Config (PROJECT_ID, DATASET, PREVIEW_TOKEN) is rewritten at build time by
 * studio/migrate/pull-i18n.ts. The defaults below keep the file inert if
 * the build step hasn't run.
 */
(function () {
    'use strict';

    const PROJECT_ID = window.ROOFY_SETTINGS?.sanityProjectId || '';
    const DATASET = window.ROOFY_SETTINGS?.sanityDataset || 'production';
    const PREVIEW_TOKEN = window.ROOFY_SETTINGS?.sanityPreviewToken || '';
    const API_VERSION = '2026-01-01';

    function isPreview() {
        try {
            return new URLSearchParams(location.search).has('preview');
        } catch (_) { return false; }
    }

    /* Sanity REST query URL */
    function apiUrl(query, params) {
        const qs = new URLSearchParams();
        qs.set('query', query);
        if (params) {
            for (const k of Object.keys(params)) qs.set(`$${k}`, JSON.stringify(params[k]));
        }
        return `https://${PROJECT_ID}.api.sanity.io/v${API_VERSION}/data/query/${DATASET}?${qs}`;
    }

    function imgUrl(asset, opts) {
        if (!asset || !asset._ref) return '';
        /* assets _ref format: image-<hash>-<w>x<h>-<format>. Build CDN URL. */
        const m = asset._ref.match(/^image-([a-f0-9]+)-(\d+x\d+)-(\w+)$/);
        if (!m) return '';
        const base = `https://cdn.sanity.io/images/${PROJECT_ID}/${DATASET}/${m[1]}-${m[2]}.${m[3]}`;
        const w = opts && opts.w;
        return w ? `${base}?w=${w}&auto=format` : base;
    }

    async function gfetch(query, params) {
        const r = await fetch(apiUrl(query, params), {
            headers: PREVIEW_TOKEN ? {Authorization: `Bearer ${PREVIEW_TOKEN}`} : {},
        });
        if (!r.ok) throw new Error(`Sanity ${r.status}`);
        return (await r.json()).result;
    }

    /* Returns same shape as /assets/data/properties.json (legacy compatible). */
    async function getProperties() {
        const q = `*[_type == "property"] | order(orderRank asc) {
            "id": slug.current, "type": category, placeholder, image,
            "titleZh": title.zh, "titleEn": title.en,
            "loc": coalesce(location.en, location.zh),
            "price": price.formatted,
            "area": coalesce(area.en, area.zh),
            beds, baths,
            "descZh": description.zh, "descEn": description.en
        }`;
        const list = await gfetch(q);
        return {
            items: list.map(function (p) { return Object.assign({}, p, {img: imgUrl(p.image && p.image.asset, {w: 1200})}); }),
        };
    }

    async function getTeam() {
        const q = `*[_type == "teamMember"] | order(orderRank asc) {
            "id": slug.current, name, nameZh,
            "role": role.en, "roleZh": role.zh,
            initials, photo
        }`;
        const list = await gfetch(q);
        return {
            members: list.map(function (m) { return Object.assign({}, m, {photo: imgUrl(m.photo && m.photo.asset, {w: 600})}); }),
        };
    }

    /* Site content + settings — used by preview to override window.I18N. */
    async function getSiteContent() {
        return gfetch(`*[_id == "siteContent"][0]`);
    }
    async function getSiteSettings() {
        return gfetch(`*[_id == "siteSettings"][0]`);
    }

    window.RoofyData = {
        isPreview: isPreview,
        getProperties: getProperties,
        getTeam: getTeam,
        getSiteContent: getSiteContent,
        getSiteSettings: getSiteSettings,
        imgUrl: imgUrl,
    };
})();
